// Encodées en base64 plutôt que référencées par URL (/documents/...) —
// html-to-image (toPng) échouait silencieusement à inliner les images JPG
// chargées depuis une URL locale lors de la rasterisation du bon de
// confirmation (résultat : zone blanche à la place de la capture dans le
// PDF/PNG généré, alors que l'image s'affichait normalement dans le DOM
// avant capture). Une data URI est déjà 'chargée', pas de round-trip réseau
// possible à rater pendant la capture.
export const PAYPAL_ENTRE_PROCHES_1 = "data:image/jpeg;base64,";
export const PAYPAL_ENTRE_PROCHES_2 = "data:image/jpeg;base64,";
